parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const payload = item.json.body || item.json;
  const event = payload.payload || payload;
  const invitee = event.invitee || {};
  const eventDetails = event.event || {};
  return {
    json: {
      eventName: eventDetails.name || event.event_type?.name || '',
      eventDate: eventDetails.start_time || '',
      eventEndTime: eventDetails.end_time || '',
      inviteeName: invitee.name || '',
      inviteeEmail: invitee.email || '',
      inviteeTimezone: invitee.timezone || '',
      location: eventDetails.location?.join_url || eventDetails.location || '',
      questionsAndAnswers: JSON.stringify(invitee.questions_and_answers || []),
      cancelUrl: invitee.cancel_url || '',
      rescheduleUrl: invitee.reschedule_url || '',
      createdAt: new Date().toISOString()
    }
  };
});

